fun counts =>
  have min := counts.min?.getD 0;
  have max := counts.max?.getD 0;
  have toFloat := fun n => n.toUInt64.toFloat;
  have toNat := fun f => f.toUInt64.toNat;
  have counts' := List.map toFloat counts;
  have μ := List.foldl (fun x1 x2 => x1 + x2) 0 counts' / toFloat counts.length;
  have stddev :=
    (List.foldl (fun x1 x2 => x1 + x2) 0 (List.map (fun i => (i - μ) ^ 2) counts') /
        toFloat counts.length).sqrt;
  [min, max, toNat stddev]

